if __name__=='__main__':
    root=Path('.data/ml/counting63-instance-v1');root.mkdir(exist_ok=True)
    manifest=json.loads(Path('.data/ml/quality63-experiment/manifest.json').read_text(encoding='utf-8'))
    annotations=[]
    for r in manifest['images']:
        if r['id'] not in BOXES:continue
        instances=[]
        for s in BOXES[r['id']].split(';'):
            if not s.strip():continue
            x,y,w,h=map(float,s.split(','));assert min(x-w/2,y-h/2)>0 and max(x+w/2,y+h/2)<512,(r['id'],s)
            instances.append({'center':[x/512,y/512],'box_xywh':[x/512,y/512,w/512,h/512],'origin':'codex_visual_review_without_model_predictions'})
        annotations.append({'id':r['id'],'image_sha256':r['sha256'],'original_split':r['split'],'split':r['split'] if r['split']!='unlabeled' else 'train','source':r['source'],'instances':instances,'count':len(instances),'note':NOTES.get(r['id'],'Conservative visible-instance working annotation; faint/unclear and original-edge-cut regions excluded.'),'reviewer':'Codex','expert_verified':False,'user_verified':False})
